sk_float any_to_float(sk_any a) {
    if (a.type == 6) return SK_NULL_float;
    sk_float r;
    switch (a.type) {
        case 0: r = sk_float_new((float)a.data.i); break;
        case 1: r = sk_float_new((float)atof(a.data.s)); break;
        case 2: r = sk_float_new(a.data.f); break;
        case 3: r = sk_float_new((float)a.data.d); break;
        case 4: r = sk_float_new(a.data.b ? 1.0f : 0.0f); break;
        default: return SK_NULL_float;
    }
    if (a.prec >= 0) r.prec = a.prec;
    return r;
}
sk_double any_to_double(sk_any a) {
    if (a.type == 6) return SK_NULL_double;
    sk_double r;
    switch (a.type) {
        case 0: r = sk_double_new((double)a.data.i); break;
        case 1: r = sk_double_new(atof(a.data.s)); break;
        case 2: r = sk_double_new((double)a.data.f); break;
        case 3: r = sk_double_new(a.data.d); break;
        case 4: r = sk_double_new(a.data.b ? 1.0 : 0.0); break;
        default: return SK_NULL_double;
    }
    if (a.prec >= 0) r.prec = a.prec;
    return r;
}
sk_bool any_to_bool(sk_any a) {
    if (a.type == 6) return SK_NULL_bool;
    switch (a.type) {
        case 0: return sk_bool_new(a.data.i != 0);
        case 1: return sk_bool_new(a.data.s[0] != '\0');
        case 2: return sk_bool_new(a.data.f != 0.0f);
        case 3: return sk_bool_new(a.data.d != 0.0);
        case 4: return sk_bool_new(a.data.b);
        default: return SK_NULL_bool;
    }
}
sk_string any_to_string(sk_any a) {
    if (a.type == 6) return sk_string_new("null");
    char buf[64];
    switch (a.type) {
        case 0: snprintf(buf, 64, "%d", a.data.i); return sk_string_new(buf);
        case 1: return sk_string_new(a.data.s);
        case 2: if (a.prec >= 0) snprintf(buf, 64, "%.*f", a.prec, a.data.f); else snprintf(buf, 64, "%f", a.data.f); return sk_string_new(buf);
        case 3: if (a.prec >= 0) snprintf(buf, 64, "%.*f", a.prec, a.data.d); else snprintf(buf, 64, "%f", a.data.d); return sk_string_new(buf);
        case 4: return sk_string_new(a.data.b ? "true" : "false");
        case 5: return sk_array_to_string((sk_array*)a.data.p);
        default: return sk_string_new("unknown");
    }
}
sk_arr any_to_arr(sk_any a) {
    if (a.type == 6) return SK_NULL_arr;
    if (a.type == 5) return sk_arr_new(sk_array_deep_copy((sk_array*)a.data.p));
    return SK_NULL_arr;
}

sk_any sk_any_add(sk_any a, sk_any b) {
    if (a.type == 6 || b.type == 6) return any_null();
    if (a.type == 1 || b.type == 1) return any_string(sk_string_concat(any_to_string(a), any_to_string(b)));
    if (a.type == 3 || b.type == 3) return any_double(sk_double_add(any_to_double(a), any_to_double(b)));
    if (a.type == 2 || b.type == 2) return any_float(sk_float_add(any_to_float(a), any_to_float(b)));
    if (a.type == 0 && b.type == 0) return any_int(sk_int_add(any_to_int(a), any_to_int(b)));
    return any_null();
}
sk_any sk_any_sub(sk_any a, sk_any b) {
    if (a.type == 6 || b.type == 6) return any_null();
    if (a.type == 3 || b.type == 3) return any_double(sk_double_sub(any_to_double(a), any_to_double(b)));
    if (a.type == 2 || b.type == 2) return any_float(sk_float_sub(any_to_float(a), any_to_float(b)));
    if (a.type == 0 && b.type == 0) return any_int(sk_int_sub(any_to_int(a), any_to_int(b)));
    return any_null();
}
sk_any sk_any_mul(sk_any a, sk_any b) {
    if (a.type == 6 || b.type == 6) return any_null();
    if (a.type == 3 || b.type == 3) return any_double(sk_double_mul(any_to_double(a), any_to_double(b)));
    if (a.type == 2 || b.type == 2) return any_float(sk_float_mul(any_to_float(a), any_to_float(b)));
    if (a.type == 0 && b.type == 0) return any_int(sk_int_mul(any_to_int(a), any_to_int(b)));
    return any_null();
}
sk_any sk_any_div(sk_any a, sk_any b) {
    if (a.type == 6 || b.type == 6) return any_null();
    if (a.type == 3 || b.type == 3) return any_double(sk_double_div(any_to_double(a), any_to_double(b)));
    if (a.type == 2 || b.type == 2) return any_float(sk_float_div(any_to_float(a), any_to_float(b)));
    if (a.type == 0 && b.type == 0) return any_int(sk_int_div(any_to_int(a), any_to_int(b)));
    return any_null();
}
sk_any sk_any_mod(sk_any a, sk_any b) {
    if (a.type == 6 || b.type == 6) return any_null();
    if (a.type == 0 && b.type == 0) return any_int(sk_int_mod(any_to_int(a), any_to_int(b)));
    return any_null();
}
sk_any sk_any_pow(sk_any a, sk_any b) {
    if (a.type == 6 || b.type == 6) return any_null();
    if (a.type == 3 || b.type == 3) return any_double(sk_double_pow(any_to_double(a), any_to_double(b)));
    if (a.type == 2 || b.type == 2) return any_float(sk_float_pow(any_to_float(a), any_to_float(b)));
    if (a.type == 0 && b.type == 0) return any_int(sk_int_pow(any_to_int(a), any_to_int(b)));
    return any_null();
}

sk_string sk_arr_to_string(sk_arr a) {
    if (a.__is_null) return sk_string_new("null");
    return sk_array_to_string(a.value);
}

sk_string sk_array_to_string(sk_array* a) {
    char* buf = malloc(1024);
    strcpy(buf, "[");
    for (int i = 0; i < a->length; i++) {
        if (i > 0) strcat(buf, ", ");
        void* elem = sk_array_get(a, i);
        if (a->elem_type == 5) {
            sk_any* any = (sk_any*)elem;
            sk_string s = any_to_string(*any);
            strcat(buf, s.__is_null ? "null" : s.value);
        } else if (a->elem_type == 0) {
            sk_int* v = (sk_int*)elem;
            char tmp[32];
            if (v->__is_null) strcat(buf, "null");
            else { snprintf(tmp, 32, "%d", v->value); strcat(buf, tmp); }
        } else if (a->elem_type == 1) {
            sk_string* v = (sk_string*)elem;
            strcat(buf, v->__is_null ? "null" : v->value);
        } else if (a->elem_type == 2) {
            sk_float* v = (sk_float*)elem;
            char tmp[32];
            if (v->__is_null) strcat(buf, "null");
            else { snprintf(tmp, 32, "%f", v->value); strcat(buf, tmp); }
        } else if (a->elem_type == 3) {
            sk_double* v = (sk_double*)elem;
            char tmp[32];
            if (v->__is_null) strcat(buf, "null");
            else { snprintf(tmp, 32, "%f", v->value); strcat(buf, tmp); }
        } else if (a->elem_type == 4) {
            sk_bool* v = (sk_bool*)elem;
            strcat(buf, v->__is_null ? "null" : (v->value ? "true" : "false"));
        } else if (a->elem_type == 6) {
            sk_arr* v = (sk_arr*)elem;
            if (v->__is_null) strcat(buf, "null");
            else { sk_string s = sk_array_to_string(v->value); strcat(buf, s.value); free(s.value); }
        }
    }
    strcat(buf, "]");
    return sk_string_new_take(buf);
}

sk_array* sk_array_deep_copy(sk_array* a) {
    sk_array* new = sk_array_new(a->elem_size, a->elem_type);
    for (int i = 0; i < a->length; i++) {
        void* elem = sk_array_get(a, i);
        switch (a->elem_type) {
            case 0: { sk_int* v = (sk_int*)elem; sk_array_push_int(new, *v); break; }
            case 1: { sk_string* v = (sk_string*)elem; sk_string c = v->__is_null ? SK_NULL_string : sk_string_new(v->value); sk_array_push_string(new, c); break; }
            case 2: { sk_float* v = (sk_float*)elem; sk_array_push_float(new, *v); break; }
            case 3: { sk_double* v = (sk_double*)elem; sk_array_push_double(new, *v); break; }
            case 4: { sk_bool* v = (sk_bool*)elem; sk_array_push_bool(new, *v); break; }
            case 5: {
                sk_any* v = (sk_any*)elem;
                sk_any c;
                if (v->type == 6) c = any_null();
                else if (v->type == 1) c = any_string(sk_string_new(v->data.s));
                else if (v->type == 5) c = any_arr(sk_arr_new(sk_array_deep_copy((sk_array*)v->data.p)));
                else c = *v;
                sk_array_push_any(new, c);
                break;
            }
            case 6: {
                sk_arr* v = (sk_arr*)elem;
                sk_arr c = v->__is_null ? SK_NULL_arr : sk_arr_new(sk_array_deep_copy(v->value));
                sk_array_push_arr(new, c);
                break;
            }
        }
    }
    return new;
}

void sk_array_deep_free(sk_array* a) {
    if (!a) return;
    for (int i = 0; i < a->length; i++) {
        void* elem = sk_array_get(a, i);
        switch (a->elem_type) {
            case 1: { sk_string* v = (sk_string*)elem; if (!v->__is_null && v->value) free(v->value); break; }
            case 5: {
                sk_any* v = (sk_any*)elem;
                if (v->type == 1 && v->data.s) free(v->data.s);
                else if (v->type == 5 && v->data.p) sk_array_deep_free((sk_array*)v->data.p);
                break;
            }
            case 6: { sk_arr* v = (sk_arr*)elem; if (!v->__is_null) sk_array_deep_free(v->value); break; }
        }
    }
    free(a->data);
    free(a);
}

